validator:
function validate(input) {
  const [{ Logs = [] }] = input;
  const seen = new Set();
  for (const [id] of Logs) {
    if (id === null) return 'Every row needs a log_id.';
    if (id < 0) return 'log_id may not be negative.';
    if (seen.has(id)) return `log_id ${id} appears twice.`;
    seen.add(id);
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const small = size === 'small';
  const count = small ? pick(9) : 2000;
  const Logs = [];
  // Walk upward: usually the next id is consecutive, sometimes a gap opens.
  let id = small ? pick(4) : pick(50);
  for (let i = 0; i < count; i++) {
    Logs.push([id]);
    id += rand() < (small ? 0.6 : 0.75) ? 1 : 2 + pick(small ? 3 : 8);
  }
  for (let i = Logs.length - 1; i > 0; i--) { const j = pick(i + 1); [Logs[i], Logs[j]] = [Logs[j], Logs[i]]; }
  return [{ Logs }];
}
